function tuneQuality(rawDt) {
  if (g.state !== 'playing') {
    perf.frames = 0;
    perf.elapsed = 0;
    perf.wait = 0;
    return;
  }
  if (perf.wait > 0) {
    perf.wait -= Math.min(0.2, rawDt);
    return;
  }

  perf.frames += 1;
